import {NextResponse} from "next/server";import {z} from "zod";import {requireVendor} from "@/lib/auth";import {connectMongoose} from "@/lib/db";import {getImageStorageProvider} from "@/lib/storage/provider";import {VehicleModel} from "@/models/Vehicle";import {VendorProfileModel} from "@/models/VendorProfile";
const schema=z.object({make:z.string().trim().min(2).max(60),model:z.string().trim().min(1).max(60),year:z.coerce.number().int().min(1950).max(new Date().getFullYear()+1),price:z.coerce.number().positive(),mileage:z.coerce.number().nonnegative(),city:z.string().trim().min(2).max(60),transmission:z.enum(["AUTOMATIC","MANUAL","CVT"]),description:z.string().trim().min(30).max(5000),imageUrl:z.union([z.literal(""),z.url({protocol:/https?/})])});
export async function POST(r:Request){const user=await requireVendor();const form=await r.formData();const parsed=schema.safeParse(Object.fromEntries(form));if(!parsed.success)return NextResponse.json({error:"Invalid listing",details:parsed.error.flatten().fieldErrors},{status:422});const file=form.get("imageFile");if(parsed.data.imageUrl&&file instanceof File&&file.size)return NextResponse.json({error:"Choose an image link or a file, not both."},{status:422});await connectMongoose();const vendor=await VendorProfileModel.findOne({userId:user.id}).select("_id status").lean();if(!vendor||vendor.status!=="APPROVED")return NextResponse.json({error:"Approved vendor status required"},{status:403});const v=parsed.data,alt=`${v.year} ${v.make} ${v.model}`,slug=`${alt}-${Date.now()}`.toLowerCase().replace(/[^a-z0-9]+/g,"-");let image:{url:string;alt:string;publicId?:string}|undefined;try{if(file instanceof File&&file.size)image=await getImageStorageProvider().upload(file,{folder:String(vendor._id),alt});else if(v.imageUrl)image={url:v.imageUrl,alt}}catch(error){return NextResponse.json({error:error instanceof Error?error.message:"Image upload failed"},{status:422})}if(!image)return NextResponse.json({error:"Add a car image link or upload an image file."},{status:422});const created=await VehicleModel.create({...v,imageUrl:undefined,vendorId:vendor._id,title:alt,slug,location:{country:"Nigeria",city:v.city},fuelType:"PETROL",bodyType:"OTHER",images:[{...image,isPrimary:true,order:0}],features:[],status:"DRAFT",inspectionStatus:"NOT_INSPECTED"});return NextResponse.redirect(new URL(`/vendor/cars/${created.id}`,r.url),303)}
